const rFIDStockVariance = `-- name: RFIDStockVariance :many
SELECT v.id AS variant_id, v.sku, p.name AS product_name, v.name AS variant_name, s.id AS store_id, s.name AS store_name,
       COALESCE(tg.n, 0)::bigint AS tag_qty, COALESCE(bal.on_hand, 0)::numeric AS system_qty
FROM (
    SELECT t.variant_id, t.store_id, count(*) AS n FROM rfid_tags t
    WHERE t.company_id = $1 AND t.store_id IS NOT NULL AND t.status IN ('IN_STOCK','ON_SHELF','RESERVED','RETURNED')
    GROUP BY t.variant_id, t.store_id
) tg
JOIN product_variants v ON v.id = tg.variant_id JOIN products p ON p.id = v.product_id
JOIN stores s ON s.id = tg.store_id JOIN org_units o ON o.id = s.org_unit_id
LEFT JOIN LATERAL (SELECT sum(b.on_hand) AS on_hand FROM inventory_balances b WHERE b.store_id = tg.store_id AND b.variant_id = tg.variant_id) bal ON true
WHERE ($2::bool OR EXISTS (SELECT 1 FROM unnest($3::text[]) sp WHERE o.path <@ sp::ltree))
  AND ($4::text = '' OR o.path <@ $4::text::ltree)
  AND ($5::uuid IS NULL OR tg.store_id = $5::uuid)
  AND (NOT $6::bool OR tg.n <> COALESCE(bal.on_hand, 0))
ORDER BY abs(tg.n - COALESCE(bal.on_hand, 0)) DESC, p.name
LIMIT $7
`

type RFIDStockVarianceParams struct {
	CompanyID  uuid.UUID  `json:"company_id"`
	AllScope   bool       `json:"all_scope"`
	ScopePaths []string   `json:"scope_paths"`
	UnderPath  string     `json:"under_path"`
	StoreID    *uuid.UUID `json:"store_id"`
	OnlyDiff   bool       `json:"only_diff"`
	RowLimit   int32      `json:"row_limit"`
}

type RFIDStockVarianceRow struct {
	VariantID   uuid.UUID       `json:"variant_id"`
	Sku         string          `json:"sku"`
	ProductName string          `json:"product_name"`
	VariantName string          `json:"variant_name"`
	StoreID     uuid.UUID       `json:"store_id"`
	StoreName   string          `json:"store_name"`
	TagQty      int64           `json:"tag_qty"`
	SystemQty   decimal.Decimal `json:"system_qty"`
}

// Tags physically recorded in a store per variant vs the system balance: the day-to-day RFID/stock reconciliation.
func (q *Queries) RFIDStockVariance(ctx context.Context, arg RFIDStockVarianceParams) ([]RFIDStockVarianceRow, error) {
	rows, err := q.db.Query(ctx, rFIDStockVariance,
		arg.CompanyID,
		arg.AllScope,
		arg.ScopePaths,
		arg.UnderPath,
		arg.StoreID,
		arg.OnlyDiff,
		arg.RowLimit,
	)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	items := []RFIDStockVarianceRow{}
	for rows.Next() {
		var i RFIDStockVarianceRow
		if err := rows.Scan(
			&i.VariantID,
			&i.Sku,
			&i.ProductName,
			&i.VariantName,
			&i.StoreID,
			&i.StoreName,
			&i.TagQty,
			&i.SystemQty,
		); err != nil {
			return nil, err
		}
		items = append(items, i)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

